import{_ as t,o as e,c as o,a2 as p}from"./chunks/framework.F7eQ-ohH.js";const d="/bzygq/assets/d23a2a53781f416d8e7cb4fa91877006.CUAkIoXL.png",n="/bzygq/assets/b838573934d14293b3ff3093a835c390._j1kOTLA.png",r="/bzygq/assets/886a43bd1b0f4fddb1bcfd20b33e2c02.BpCGKikx.png",l="/bzygq/assets/6a2dc40215aa497897d39b86e46fadd5.CImW0qwe.png",u=JSON.parse('{"title":"Seata 分布式事务与一致性边界","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/Spring Cloud/07-Seata分布式事务与一致性边界.md","filePath":"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/Spring Cloud/07-Seata分布式事务与一致性边界.md","lastUpdated":1788929995000}'),i={name:"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/Spring Cloud/07-Seata分布式事务与一致性边界.md"};function T(s,a,g,S,C,c){return e(),o("div",null,[...a[0]||(a[0]=[p('<h1 id="seata-分布式事务与一致性边界" tabindex="-1">Seata 分布式事务与一致性边界 <a class="header-anchor" href="#seata-分布式事务与一致性边界" aria-label="Permalink to &quot;Seata 分布式事务与一致性边界&quot;">​</a></h1><p>Seata 是一套面向微服务架构的分布式事务解决方案，它的核心目标不是把所有跨服务写操作都包装成强一致事务，而是在确实需要跨资源一致性的链路中，提供全局事务协调、分支事务注册、回滚补偿和并发冲突控制能力。理解 Seata 时，第一步要先把问题边界讲清楚：微服务拆分以后，订单、库存、账户、优惠券、积分等数据可能分散在不同服务和数据库中，本地事务只能保证单个数据源内部的原子性，无法天然覆盖一次业务操作中的多次远程调用和多库写入。</p><p>传统单体应用里，一个业务方法通常可以依赖数据库本地事务完成提交或回滚；微服务拆分后，远程调用可能成功、失败、超时或返回未知状态，多个服务之间也不再共享同一个数据库连接。此时系统必须在强一致、最终一致、吞吐量、侵入成本和失败补偿之间做取舍。Seata 的价值在于降低一部分关系型数据库场景下的分布式事务接入成本，但它引入了 TC 通信、undo_log、全局锁、二阶段处理和回滚校验，因此不能被当作微服务的一键保险。</p><p>从工程角度看，分布式事务更像一种昂贵的治理手段。能通过聚合边界调整把强一致写操作留在同一个服务内，就优先调整模型；能通过可靠消息、状态机、补偿任务实现可接受的最终一致，就不必急着引入全局事务；只有当业务确实要求短链路、强一致、关系型数据库写入可控，并且吞吐量和锁冲突经过评估时，才适合讨论 Seata AT、TCC、Saga 或 XA 的落地方式。</p><h2 id="一、分布式一致性的业务边界" tabindex="-1">一、分布式一致性的业务边界 <a class="header-anchor" href="#一、分布式一致性的业务边界" aria-label="Permalink to &quot;一、分布式一致性的业务边界&quot;">​</a></h2><p>分布式事务出现的根本原因是数据所有权被拆开了。以创建订单为例，订单服务要写订单记录，库存服务要扣减库存，账户服务可能要冻结余额，营销服务可能要核销优惠券。每个服务都有自己的数据库，本地事务提交成功并不代表整条业务链路都成功；如果订单写入成功但库存扣减失败，系统就会出现业务状态不一致。</p><p>不过，“跨服务写入”并不自动等于“必须使用分布式事务”。很多业务允许短暂不一致，只要最终能通过重试、补偿、对账和状态机收敛即可。例如订单创建成功后异步扣减积分，短时间内积分状态落后并不一定影响主交易；通知、日志、搜索索引、统计报表这类派生数据，更适合通过消息和补偿任务处理。如果为了这些场景强行加全局事务，系统会在性能、可用性和复杂度上付出过高成本。</p><p>真正需要重点评估强一致方案的场景通常具备几个特征：业务状态之间存在不可接受的中间错误，写入链路较短，参与方数量有限，资源主要是支持事务的关系型数据库，并且失败后能够通过业务或技术手段恢复。例如资金冻结、库存预留、核心订单状态迁移，往往比日志写入、通知发送、报表同步更值得讨论分布式事务。</p><p>在面试或项目复盘里，可以把一致性边界表述为三层。第一层是领域建模层，尽量让强一致约束落在同一个聚合和同一个本地事务内。第二层是异步最终一致层，通过 MQ、状态机、补偿任务、幂等和对账处理可延迟的协作。第三层才是分布式事务层，对少数短链路、强一致、可控资源使用 Seata 或 TCC 等方案。这样表达比直接说“我们用了 Seata 保证一致性”更接近真实工程。</p><h2 id="二、tc、tm、rm-的协作结构" tabindex="-1">二、TC、TM、RM 的协作结构 <a class="header-anchor" href="#二、tc、tm、rm-的协作结构" aria-label="Permalink to &quot;二、TC、TM、RM 的协作结构&quot;">​</a></h2><p>Seata 的基本结构由三个角色组成：TC、TM 和 RM。TC 是 Transaction Coordinator，即事务协调者，负责维护全局事务状态、分支事务状态和全局锁信息；TM 是 Transaction Manager，即事务管理器，负责发起、提交或回滚全局事务，常见入口是业务方法上的 @GlobalTransactional；RM 是 Resource Manager，即资源管理器，负责管理具体数据源上的分支事务，向 TC 注册分支、上报执行状态，并在全局回滚时执行补偿。</p><p>一个典型调用链可以这样理解：业务入口方法进入 TM 管理范围后，TM 向 TC 申请开启全局事务，TC 返回一个全局事务 ID，也就是 XID。随后业务服务调用下游服务时，XID 会随着 RPC 上下文、HTTP Header 或框架拦截器向后传播。每个参与数据库写入的服务都通过 Seata 代理数据源接入 RM，RM 在执行本地 SQL 时识别当前 XID，把本地事务注册为全局事务下的分支事务。</p><p>事务上下文是 Seata 能把多个服务串成一条全局事务链路的关键。入口服务如果开启了全局事务，但下游调用没有正确传播 XID，下游写入就会退化成本地事务，TC 无法感知这个分支，后续全局回滚也无法自动补偿。因此排查 Seata 问题时，不能只看 @GlobalTransactional 是否存在，还要看 RPC 拦截器、线程切换、异步执行、网关透传和数据源代理是否让 XID 贯穿了所有需要参与事务的分支。</p><p>从职责分工看，TM 管的是“全局事务生命周期”，RM 管的是“本地资源如何加入全局事务”，TC 管的是“全局状态和分支协调”。这三个角色的边界要分清：业务代码一般直接接触 TM 注解和本地数据库操作；RM 通过数据源代理、SQL 解析和分支注册工作；TC 是独立事务协调服务，需要具备可用性、存储能力和网络连通性。如果 TC 不可用，开启新全局事务、注册分支、申请全局锁和二阶段处理都会受影响。</p><h2 id="三、at-模式的一阶段与二阶段" tabindex="-1">三、AT 模式的一阶段与二阶段 <a class="header-anchor" href="#三、at-模式的一阶段与二阶段" aria-label="Permalink to &quot;三、AT 模式的一阶段与二阶段&quot;">​</a></h2><p>AT 模式是 Seata 中常见的低侵入事务模式，它把一次全局事务拆成两个阶段。第一阶段执行业务 SQL，并在本地事务中完成数据镜像记录、分支注册和本地提交；第二阶段根据全局事务结果执行提交清理或回滚补偿。它看起来像两阶段提交，但与传统 XA 的资源锁定方式不同：AT 一阶段会提交本地事务，释放本地数据库锁，再通过 undo_log 和全局锁维护后续回滚能力与全局写冲突控制。</p><p><img src="'+d+'" alt="images/07-seata-at-two-phase.png"></p><p>images/07-seata-at-two-phase.png</p><p>一阶段的核心动作可以按顺序理解。RM 拦截业务 SQL 后，先解析要修改的数据范围，查询并记录修改前的数据镜像，也就是 before image。随后执行业务 SQL，得到修改后的 after image，并把 before image、after image、业务 SQL、表名、主键等信息写入 undo_log。这些动作与业务数据修改处在同一个本地事务中，所以只要本地事务提交成功，业务数据和 undo_log 就能保持一致。接着 RM 向 TC 注册分支事务，并申请相关行的全局锁；分支执行完成后，本地事务提交。</p><p>二阶段提交比较轻。全局事务如果最终提交，说明所有分支都已完成一阶段提交，TC 会通知 RM 进入提交阶段。AT 模式下，提交阶段通常不需要再次修改业务表，主要是异步删除对应的 undo_log，所以提交成本相对较低。也正因为一阶段已经提交了本地事务，AT 在正常提交路径上的体验更接近“先写入业务数据，再异步清理事务痕迹”。</p><p>二阶段回滚才是 AT 的重点。全局事务如果失败，TC 会通知各个 RM 回滚对应分支。RM 根据 undo_log 中的 before image 构造反向补偿 SQL，将数据恢复到一阶段之前的状态。回滚前还要做镜像校验：当前数据库中的数据应当与 after image 一致，才能说明一阶段提交后的数据没有被其他非预期事务修改。若当前数据与 after image 不一致，就可能发生了脏写或外部修改，直接覆盖回滚会破坏别人已经提交的数据。</p><p>因此，AT 模式不是数据库层面的魔法撤销键。它依赖几个前提：业务 SQL 能被 Seata 正确解析；修改行有明确主键；本地事务、undo_log 和分支注册能正确完成；全局锁能防住全局事务之间的写写冲突；回滚时数据没有被全局事务之外的写入破坏。只要其中某个条件不满足，AT 的自动回滚能力就会变弱，甚至需要人工介入。</p><h2 id="四、undo-log、全局锁与脏写校验" tabindex="-1">四、undo_log、全局锁与脏写校验 <a class="header-anchor" href="#四、undo-log、全局锁与脏写校验" aria-label="Permalink to &quot;四、undo\\_log、全局锁与脏写校验&quot;">​</a></h2><p><img src="'+n+'" alt="images/07-seata-global-lock-dirty-write.png"></p><p>images/07-seata-global-lock-dirty-write.png</p><p>undo_log 是 AT 模式能够回滚的基础。它记录了分支事务执行前后的数据镜像，以及回滚所需的上下文信息。业务表发生写入时，Seata 不是简单记录一条反向 SQL，而是记录足够的信息用于判断当前数据是否仍然处在可回滚状态。这样做的好处是回滚更可靠，坏处是每次受管写操作都会增加额外查询、序列化、写日志和清理成本。</p><p>全局锁解决的是全局事务之间对同一行数据的写写冲突。假设两个全局事务同时扣减同一条库存记录，如果没有全局锁，它们可能都在一阶段提交本地事务，后续任意一个全局事务回滚都会影响另一个事务的结果。Seata 通过 TC 维护全局锁，让一个分支在修改某行数据时先占用对应的全局锁；其他全局事务再修改同一行时，会出现等待、重试或失败。全局锁并不等同于数据库本地锁，它的目标是跨分支、跨服务、跨本地事务提交之后仍然能感知写冲突。</p><p>脏写校验是 AT 回滚安全性的最后防线。分支一阶段提交后，本地数据库锁已经释放，此时如果有一个未纳入 Seata 管理的本地事务直接修改了同一行，数据库当前值就不再等于 undo_log 中记录的 after image。全局事务回滚时，如果 RM 仍然把 before image 写回去，就会覆盖这个本地事务的合法修改。为避免这种情况，Seata 会检查当前数据与 after image 是否一致；不一致时，通常会认为存在脏写风险，回滚失败并进入异常处理流程。</p><p>在工程落地中，undo_log 和全局锁会带来几个明确影响。第一，业务库必须准备 undo_log 表，账号权限、字符集、索引和清理策略都要正确。第二，热点行会放大全局锁竞争，例如库存、账户余额、单行计数器这类高并发写入容易拖慢整条链路。第三，批量大事务会生成大量镜像和日志，增加数据库压力。第四，未被 Seata 代理的数据源、手写 JDBC、绕过框架的更新、触发器或存储过程，都可能让回滚边界变得不可控。</p><p>面试回答这里要强调一句：undo_log 负责“如何回滚”，全局锁负责“减少并发写冲突”，脏写校验负责“判断还能不能安全回滚”。三者组合起来，才构成 AT 的一致性能力。只背“AT 一阶段写 undo_log，二阶段回滚”是不够的，因为真正的追问通常会落到并发修改、非 Seata 写入、热点数据和回滚失败。</p><h2 id="五、at、tcc、saga、xa-与可靠消息的选型" tabindex="-1">五、AT、TCC、Saga、XA 与可靠消息的选型 <a class="header-anchor" href="#五、at、tcc、saga、xa-与可靠消息的选型" aria-label="Permalink to &quot;五、AT、TCC、Saga、XA 与可靠消息的选型&quot;">​</a></h2><p>分布式一致性方案没有单一最优解，不同方案解决的问题和代价不同。AT 适合低侵入、关系型数据库、普通 DML、链路较短的强一致场景；TCC 适合业务能够显式设计 Try、Confirm、Cancel 的资源预留场景；Saga 适合长流程、跨系统、最终一致、需要业务补偿的场景；XA 更接近数据库资源管理器参与的强一致协议，隔离性强但资源锁定和性能代价更明显；可靠消息适合异步解耦和最终一致链路。</p><p><img src="'+r+'" alt="images/07-distributed-consistency-selection.png"></p><p>images/07-distributed-consistency-selection.png</p><table tabindex="0"><thead><tr><th>方案</th><th>核心机制</th><th>适合场景</th><th>主要代价</th></tr></thead><tbody><tr><td>Seata AT</td><td>SQL 解析、undo_log、全局锁、回滚补偿</td><td>关系型数据库、普通写操作、短链路强一致</td><td>SQL 边界、全局锁竞争、日志和 TC 通信开销</td></tr><tr><td>TCC</td><td>Try 预留资源，Confirm 确认，Cancel 取消</td><td>资金冻结、库存预留、额度占用</td><td>业务侵入高，幂等、悬挂、空回滚复杂</td></tr><tr><td>Saga</td><td>本地事务串联，失败后按补偿动作回退</td><td>长流程、跨系统、人工或外部环节较多</td><td>只保证最终一致，补偿逻辑要精心设计</td></tr><tr><td>XA</td><td>数据库资源参与二阶段提交</td><td>少量资源、强一致要求高、数据库支持完善</td><td>锁持有时间长，吞吐和可用性压力较大</td></tr><tr><td>可靠消息</td><td>本地事务配合消息投递、重试、死信、对账</td><td>异步通知、状态同步、派生数据更新</td><td>需要处理幂等、顺序、重复消费和补偿</td></tr></tbody></table><p>AT 与 TCC 的区别经常被追问。AT 把回滚逻辑更多交给框架，通过数据镜像自动补偿，开发侵入低，但前提是 SQL 可解析、数据可镜像、回滚可覆盖。TCC 则把一致性动作显式暴露给业务：Try 阶段预留资源，Confirm 阶段确认资源，Cancel 阶段释放资源。它更适合资金和库存这类业务，因为“冻结”和“解冻”本来就是业务语义的一部分；但开发者必须处理幂等、空回滚、悬挂、重复确认、超时补偿等问题。</p><p>Saga 更适合长事务。比如一个业务流程要跨订单、合同、审批、物流、第三方接口，整个流程可能持续数分钟甚至数小时，此时用 AT 或 XA 长时间维持全局事务并不现实。Saga 会把流程拆成多个本地事务，每一步都有对应补偿动作，失败时按反向顺序补偿。它的特点是流程清晰、适合异构系统，但不能保证中间状态对外完全不可见，因此需要业务状态机、查询口径和补偿语义配合。</p><p>可靠消息通常是微服务一致性里更常用的方案。订单创建后发送库存扣减消息，库存服务消费后更新状态；如果消费失败，通过重试、死信队列、人工补偿或定时对账处理。它牺牲的是短时间强一致，换来的是解耦、削峰和可恢复性。对于通知、积分、报表、搜索索引、状态同步等场景，可靠消息往往比 Seata 更自然。</p><h2 id="六、性能影响与事务边界控制" tabindex="-1">六、性能影响与事务边界控制 <a class="header-anchor" href="#六、性能影响与事务边界控制" aria-label="Permalink to &quot;六、性能影响与事务边界控制&quot;">​</a></h2><p><img src="'+l+'" alt="images/07-seata-transaction-context-loss.png"></p><p>images/07-seata-transaction-context-loss.png</p><p>Seata 会影响性能，这一点在项目表达中要说清楚。AT 模式的每次受管写入都可能增加 SQL 解析、前后镜像查询、undo_log 写入、TC 网络通信、全局锁申请、分支状态上报和二阶段处理。正常提交路径虽然二阶段较轻，但一阶段的额外成本仍然存在；回滚路径还要执行镜像校验和补偿 SQL，复杂度更高。</p><p>性能问题通常出现在四类位置。第一类是热点数据，全局锁竞争会让并发写入排队或失败，库存扣减、余额更新、单行配置开关、计数器都要特别谨慎。第二类是大事务，一个全局事务中包含大量行更新或多个远程调用，会生成大量 undo_log，也会拉长全局事务存活时间。第三类是慢调用，全局事务包住外部接口、文件操作、复杂计算或下游慢服务，会使全局锁和事务上下文停留太久。第四类是 TC 与数据库基础设施，TC 存储、网络延迟、连接池、数据库索引和清理任务都会影响整体表现。</p><p>控制事务边界的原则是让全局事务只包住确实需要一致性的数据库变更。外部通知、日志写入、消息投递、搜索索引更新、缓存刷新和第三方接口调用，应尽量通过事务后事件、可靠消息、补偿任务或状态机处理。对于下游服务调用，也要避免在一个全局事务里串太多参与方；参与方越多，失败概率、超时概率和排查难度都会上升。</p><p>容量评估时不能只看功能跑通。需要压测包含 Seata 的真实链路，观察全局事务耗时、分支注册耗时、全局锁等待时间、undo_log 增长速度、TC 负载、数据库 P95/P99 延迟和回滚成功率。尤其是库存、账户、订单状态这类核心写路径，要用接近生产的数据分布测试热点冲突，而不是只用均匀随机数据验证吞吐。</p><p>如果项目里最终决定使用 AT，可以准备几条落地规范：全局事务方法保持短小；参与方数量可控；禁止在全局事务内做不可补偿外部副作用；所有参与库统一接入 Seata 数据源代理；业务表必须有主键；undo_log 表按规范创建并监控容量；对热点资源优先考虑 TCC、库存分段、业务预留或异步化，而不是让 AT 独自承担高并发扣减。</p><h2 id="七、常见故障与排查路径" tabindex="-1">七、常见故障与排查路径 <a class="header-anchor" href="#七、常见故障与排查路径" aria-label="Permalink to &quot;七、常见故障与排查路径&quot;">​</a></h2><p>Seata 排查要从“全局事务是否形成闭环”入手。第一步看 TM 是否真正开启全局事务，包括 @GlobalTransactional 是否生效、方法是否经过 Spring 代理、异常是否向外抛出、事务超时时间是否合理。常见错误是注解加在内部自调用方法上，代理没有生效；或者业务代码捕获异常后没有继续抛出，导致 TM 判断业务成功并提交全局事务。</p><p>第二步看事务上下文是否传播。下游服务日志中应该能看到相同 XID，RPC 框架或 HTTP 调用链要能透传事务上下文。跨线程、异步任务、线程池、定时任务、消息消费和手动创建线程是高风险区域，因为 XID 通常存在线程上下文中，线程切换后可能丢失。若下游没有 XID，它的数据库写入就不会注册成分支事务。</p><p>第三步看 RM 和数据源代理。参与事务的数据库操作必须通过 Seata 代理数据源执行，分支事务才能注册到 TC。若某些模块使用了未代理的数据源、手写连接、独立 MyBatis 配置、多数据源切换异常，可能出现业务数据已写入但 TC 看不到分支的情况。排查时要结合应用启动日志、数据源 Bean、Seata 客户端日志和分支注册记录。</p><p>第四步看 undo_log 与全局锁。若回滚失败，要检查 undo_log 表是否存在、字段是否正确、权限是否足够、记录是否写入、镜像校验是否通过。若出现全局锁等待或冲突，要定位冲突表、主键、事务 XID 和持锁时间，判断是否存在热点行、大事务、超长事务或未及时完成的分支。全局锁问题不要只调大超时时间，先要判断业务模型是否把高并发写入集中到了少数行。</p><p>第五步看 TC 服务状态。TC 不只是一个旁路组件，它承载全局事务状态、分支状态和锁信息。TC 配置错误、注册发现异常、网络不通、存储不可用、时钟或版本不一致，都可能导致开启事务、注册分支、提交回滚或锁申请失败。线上环境还要关注 TC 的高可用部署、存储模式、日志级别、连接池和监控告警。</p><p>可以把排查口径整理成一条链路：入口是否开启全局事务，XID 是否向下游传播，分支是否注册成功，undo_log 是否写入，全局锁是否申请成功，业务异常是否触发回滚，二阶段通知是否到达 RM，回滚时镜像校验是否通过。按这条链路排查，能避免只盯着某一个异常堆栈。</p><h2 id="八、项目表达与面试追问" tabindex="-1">八、项目表达与面试追问 <a class="header-anchor" href="#八、项目表达与面试追问" aria-label="Permalink to &quot;八、项目表达与面试追问&quot;">​</a></h2><p>在项目里讲 Seata，最重要的是先讲取舍，再讲使用。一个成熟的表达可以是：我们不会把所有跨服务写操作都放进 Seata，而是先按业务一致性要求分层。能收敛到单服务本地事务的，优先调整聚合和服务边界；能接受短暂不一致的，用 MQ、重试、幂等、补偿和对账；只有少数短链路、强一致、关系型数据库写入，才评估 Seata AT 或 TCC。</p><p>如果项目确实用了 Seata AT，可以这样展开：入口服务通过 @GlobalTransactional 开启全局事务，TM 向 TC 注册全局事务并生成 XID；调用下游服务时通过 Feign 或 RPC 拦截器透传 XID；各服务的数据源由 Seata 代理，RM 执行业务 SQL 时生成前后镜像并写入 undo_log，同时向 TC 注册分支并申请全局锁；全局提交时异步清理日志，失败时根据 undo_log 做回滚补偿，并通过后镜像校验避免覆盖外部修改。</p><p>面试官常问“Seata AT 为什么低侵入”。回答时不要只说“加注解就行”。更准确的说法是：AT 把分支事务注册、SQL 解析、镜像记录、全局锁申请和回滚补偿封装在数据源代理与 RM 中，业务代码主要保留原来的本地 SQL 写法，因此侵入较低。但低侵入不代表无成本，它要求 SQL 可解析、表有主键、数据源被代理、undo_log 表存在，并且业务副作用能被数据库镜像覆盖。</p><p>如果被问“Seata 回滚失败怎么办”，回答要落到脏写和上下文。先看是否存在全局事务之外的写入导致当前数据与 after image 不一致；再看下游分支是否丢失 XID、是否绕过代理数据源、是否没有写入 undo_log；还要看异常是否被吞、超时是否触发、TC 是否通知到 RM。对于已经发生的脏写，通常不能简单强制覆盖，需要结合业务记录、审计日志、对账数据和补偿脚本人工恢复。</p><p>如果被问“为什么不用 Seata 处理所有一致性问题”，可以从四个角度回答。第一，很多业务只要求最终一致，可靠消息更适合异步解耦。第二，AT 主要覆盖关系型数据库 DML，不适合自动回滚外部接口、文件、缓存、消息副作用和复杂存储。第三，Seata 会增加性能开销，高并发热点写会受到全局锁影响。第四，事务边界越大，失败概率和排查成本越高，所以架构上要先做业务边界和状态机设计。</p><h2 id="九、学习自测与掌握标准" tabindex="-1">九、学习自测与掌握标准 <a class="header-anchor" href="#九、学习自测与掌握标准" aria-label="Permalink to &quot;九、学习自测与掌握标准&quot;">​</a></h2><ol><li>Seata 中 TC、TM、RM 分别负责什么？为什么只在入口方法上加 @GlobalTransactional，还不能说明下游服务一定加入了同一个全局事务？</li></ol><p>答案要点：TC 维护全局事务、分支事务和全局锁状态；TM 发起、提交或回滚全局事务；RM 管理本地资源并注册分支事务。下游是否加入同一个全局事务，取决于 XID 是否传播、数据源是否被 Seata 代理、分支是否注册成功以及本地写入是否处在 RM 管理范围内。</p><ol><li>AT 模式一阶段为什么要写 undo_log？二阶段提交和二阶段回滚分别做什么？</li></ol><p>答案要点：一阶段写 undo_log 是为了记录业务数据修改前后的镜像，使全局回滚时能够生成补偿操作。全局提交时，RM 通常异步删除 undo_log；全局回滚时，RM 根据 before image 恢复数据，并用 after image 做脏写校验，避免覆盖其他已提交修改。</p><ol><li>全局锁解决什么问题？它为什么不能替代所有并发控制？</li></ol><p>答案要点：全局锁主要解决多个全局事务对同一行数据的写写冲突，避免一阶段本地提交后不同全局事务互相破坏回滚语义。它不能替代数据库本地锁、业务幂等、库存模型和热点治理，也不能防住所有全局事务之外的直接写入。</p><ol><li>什么场景更适合可靠消息，而不是 Seata AT？</li></ol><p>答案要点：异步通知、积分变更、搜索索引、报表统计、状态同步、日志记录等可以接受短暂不一致的场景更适合可靠消息。可靠消息通过本地事务、消息确认、消费重试、死信、幂等和补偿实现最终一致，通常比全局事务更解耦、更适合高吞吐链路。</p><ol><li>Seata 线上回滚失败时，排查顺序应该怎样组织？</li></ol><p>答案要点：先确认全局事务是否开启，异常是否触发回滚；再确认 XID 是否传到下游，分支是否注册；随后检查代理数据源、undo_log 写入、全局锁冲突、TC 状态；最后看回滚时当前数据是否与 after image 一致，是否存在脏写或绕过 Seata 的本地修改。</p><p>掌握本章的标准不是能背出几个模式名称，而是能把分布式一致性问题放回业务边界中判断：哪些地方应该本地事务解决，哪些地方适合消息最终一致，哪些地方值得用 Seata AT，哪些地方必须用 TCC 或业务状态机。能讲清这个取舍，再讲 TC/TM/RM、AT 两阶段、undo_log、全局锁、脏写校验和排查链路，Seata 相关面试基本就不会停留在概念层。</p>',71)])])}const h=t(i,[["render",T]]);export{u as __pageData,h as default};
